                .verifyComplete();

        itemEntity2.setOrdinal(null);

        defaultDictionaryItemService
                .save(Flux.just(itemEntity, itemEntity2))
                .then()
                .as(StepVerifier::create)
                .expectErrorMessage("error.ordinal_can_not_null")
